mapper.select:
SELECT (@i :=@i + 1) AS seq_number, qqc.quotation_cashflow_id, qqc.quotation_id, qqc.cf_item, qqc.cf_type, qqc.cf_direction, qqc.times, qqc.due_date, qqc.due_amount, hci.description as cashflow_name, qqc.description, case qqc.cf_direction when 'OUTFLOW' then '流出' else '流入' end cf_item_desc_n, case qqc.cf_direction when 'OUTFLOW' then '流出' else '流入' end cf_item_desc, (@ii :=@ii + 1) as other_cashflow_seq_number, (SELECT ccc.write_off_flag FROM con_contract_cashflow ccc, con_contract cc WHERE cc.quotation_id = q.quotation_id AND cc.contract_id = ccc.contract_id AND ccc.cf_item = qqc.cf_item and cc.data_class = 'NORMAL' AND ccc.times = qqc.times) AS write_off_flag FROM (SELECT @i := 0) AS row_seq, (SELECT @i := 0) AS row_seq1, prj_quotation q, prj_quotation_cashflow qqc LEFT JOIN hls_cashflow_item hci ON hci.cf_item = qqc.cf_item WHERE qqc.quotation_id = q.quotation_id and qqc.cf_item in (1000,1001)
AND q.source_document_id = #{sourceDocumentId}
AND q.quotation_id = #{quotationId}
AND q.source_document_category = #{sourceDocumentCategory}
AND q.data_class = #{dataClass}
AND q.document_id = #{documentId}
order by qqc.quotation_id asc

SELECT TABNEXT.* FROM (SELECT temp.*, (temp.the_principal + temp.the_interest) the_receipt, (temp.the_principal + temp.the_interest + temp.the_consulting_service_fee + temp.the_margin + temp.the_deposit+the_lease_charge+the_residual_value+the_down_payment) the_cash_flow FROM (SELECT pqc.DUE_DATE DUE_DATE, MAX(pqc.CALC_DATE) CALC_DATE, SUM(CASE WHEN pqc.CF_ITEM = 1 THEN nvl(pqc.PRINCIPAL, 0) ELSE 0 END) the_principal, SUM(CASE WHEN pqc.CF_ITEM = 1 THEN nvl(pqc.INTEREST, 0) ELSE 0 END) the_interest, SUM(CASE WHEN pqc.CF_ITEM = 4 THEN nvl(pqc.DUE_AMOUNT, 0) ELSE 0 END) the_consulting_service_fee, SUM(CASE WHEN pqc.CF_ITEM =3 THEN nvl(pqc.DUE_AMOUNT, 0) ELSE 0 END) the_lease_charge, SUM(CASE WHEN pqc.CF_ITEM =8 THEN nvl(pqc.DUE_AMOUNT, 0) ELSE 0 END) the_residual_value, SUM(CASE WHEN pqc.CF_ITEM =2 THEN nvl(pqc.DUE_AMOUNT, 0) ELSE 0 END) the_down_payment, SUM(CASE WHEN pqc.CF_ITEM = 51 THEN nvl(pqc.DUE_AMOUNT, 0) WHEN pqc.CF_ITEM = 52 THEN -nvl(pqc.DUE_AMOUNT, 0) ELSE 0 END) the_margin, SUM(CASE WHEN pqc.CF_ITEM = 0 THEN nvl(-pqc.DUE_AMOUNT, 0) ELSE 0 END) the_deposit, pqc.quotation_id, pqc.times FROM prj_QUOTATION_CASHFLOW pqc, prj_quotation pq WHERE 1 = 1 and pq.quotation_id=pqc.quotation_id and pqc.times!=-1000
AND pq.source_document_id = #{sourceDocumentId}
AND pq.quotation_id = #{quotationId}
AND pq.source_document_category = #{sourceDocumentCategory}
AND pq.data_class = #{dataClass}
AND pq.document_id = #{documentId}
GROUP BY pqc.DUE_DATE,pqc.times,pqc.quotation_id)temp ORDER BY temp.due_date) TABNEXT

select * from prj_quotation_cashflow pqc
WHERE 1=1

    and pqc.quotation_id = #{quotationId}

SELECT qqc.*, hci.description as cf_item_n, ( SELECT ccc.write_off_flag FROM con_contract_cashflow ccc, con_contract cc WHERE cc.quotation_id = q.quotation_id AND cc.contract_id = ccc.contract_id AND ccc.cf_item = qqc.cf_item and cc.data_class='NORMAL' AND ccc.times = qqc.times ) AS write_off_flag FROM prj_quotation q, prj_quotation_cashflow qqc LEFT JOIN hls_cashflow_item hci ON hci.cf_item = qqc.cf_item WHERE qqc.quotation_id = q.quotation_id and qqc.times!=-1000
AND q.source_document_id = #{sourceDocumentId}
AND q.quotation_id = #{quotationId}
AND q.source_document_category = #{sourceDocumentCategory}
AND q.data_class = #{dataClass}
AND q.document_id = #{documentId}
order by qqc.times asc,qqc.quotation_cashflow_id

SELECT qqc.*, hci.description as cf_item_n, (@i :=@i + 1) as other_cashflow_seq_number, ( SELECT ccc.write_off_flag FROM con_contract_cashflow ccc, con_contract cc WHERE cc.quotation_id = q.quotation_id AND cc.contract_id = ccc.contract_id AND ccc.cf_item = qqc.cf_item and cc.data_class='NORMAL' AND ccc.times = qqc.times ) AS write_off_flag FROM (SELECT @i := 0) AS row_seq, prj_quotation q, prj_quotation_cashflow qqc LEFT JOIN hls_cashflow_item hci ON hci.cf_item = qqc.cf_item WHERE qqc.quotation_id = q.quotation_id and qqc.cf_item in(0)
AND q.source_document_id = #{sourceDocumentId}
AND q.quotation_id = #{quotationId}
AND q.source_document_category = #{sourceDocumentCategory}
AND q.data_class = #{dataClass}
AND q.document_id = #{documentId}
order by qqc.quotation_id asc

SELECT rowId other_cashflow_seq_number, qqc.quotation_cashflow_id, qqc.due_date, qqc.due_amount, qqc.pay_method, qqc.pay_object, qqc.pay_method pay_method_n, qqc.pay_object pay_object_n, FROM prj_quotation q, prj_quotation_cashflow qqc LEFT JOIN hls_cashflow_item hci ON hci.cf_item = qqc.cf_item WHERE qqc.quotation_id = q.quotation_id and qqc.cf_item in(0)
AND q.source_document_id = #{sourceDocumentId}
AND q.quotation_id = #{quotationId}
AND q.source_document_category = #{sourceDocumentCategory}
AND q.data_class = #{dataClass}
AND q.document_id = #{documentId}
order by qqc.quotation_id asc

SELECT TABNEXT.* FROM (SELECT temp.*, (temp.the_principal + temp.the_interest) the_receipt, (temp.the_principal + temp.the_interest + temp.the_consulting_service_fee + temp.the_margin + temp.the_deposit+the_lease_charge+the_residual_value+the_down_payment) the_cash_flow FROM (SELECT hci.description as cf_item_n, case pqc.cf_direction when 'OUTFLOW' then '流出' else '流入' end cf_direction_n, pqc.DUE_AMOUNT, pqc.NET_DUE_AMOUNT, pqc.VAT_DUE_AMOUNT, pqc.DUE_DATE, MAX(pqc.CALC_DATE) CALC_DATE, SUM(CASE WHEN pqc.CF_ITEM = 1 THEN nvl(pqc.PRINCIPAL, 0) ELSE 0 END) the_principal, SUM(CASE WHEN pqc.CF_ITEM = 1 THEN nvl(pqc.INTEREST, 0) ELSE 0 END) the_interest, SUM(CASE WHEN pqc.CF_ITEM = 4 THEN nvl(pqc.DUE_AMOUNT, 0) ELSE 0 END) the_consulting_service_fee, SUM(CASE WHEN pqc.CF_ITEM =3 THEN nvl(pqc.DUE_AMOUNT, 0) ELSE 0 END) the_lease_charge, SUM(CASE WHEN pqc.CF_ITEM =8 THEN nvl(pqc.DUE_AMOUNT, 0) ELSE 0 END) the_residual_value, SUM(CASE WHEN pqc.CF_ITEM =2 THEN nvl(pqc.DUE_AMOUNT, 0) ELSE 0 END) the_down_payment, SUM(CASE WHEN pqc.CF_ITEM = 51 THEN nvl(pqc.DUE_AMOUNT, 0) WHEN pqc.CF_ITEM = 52 THEN -nvl(pqc.DUE_AMOUNT, 0) ELSE 0 END) the_margin, SUM(CASE WHEN pqc.CF_ITEM = 0 THEN nvl(-pqc.DUE_AMOUNT, 0) ELSE 0 END) the_deposit, pqc.quotation_id, pqc.times FROM prj_quotation pq, prj_QUOTATION_CASHFLOW pqc LEFT JOIN hls_cashflow_item hci ON hci.cf_item = pqc.cf_item WHERE 1 = 1 and pq.quotation_id=pqc.quotation_id and pqc.times!=-1000
AND pq.source_document_id = #{sourceDocumentId}
AND pq.quotation_id = #{quotationId}
AND pq.source_document_category = #{sourceDocumentCategory}
AND pq.data_class = #{dataClass}
AND pq.document_id = #{documentId}
GROUP BY pqc.DUE_DATE,pqc.DUE_AMOUNT, pqc.NET_DUE_AMOUNT, pqc.VAT_DUE_AMOUNT,pqc.times,pqc.quotation_id,hci.description,pqc.cf_direction)temp ORDER BY temp.due_date) TABNEXT

SELECT SUM(fqc.due_amount) due_amount, times, sum(nvl(principal,0)) principal, sum(nvl(interest,0)) interest, due_date, SUM(fqc.due_amount - nvl(fqc.write_off_amount,0)) unreceived_amount, SUM(nvl(fqc.write_off_amount,0)) received_amount FROM fct_quotation_cashflow fqc WHERE cf_item IN (54, 55) AND cf_status = 'RELEASE'
and fqc.contract_id = #{contractId}
GROUP BY times,due_date

SELECT * FROM prj_quotation_cashflow pqc WHERE pqc.cf_item = 1 and pqc.cf_type = 1 and pqc.cf_direction = 'INFLOW' AND pqc.cf_status = 'RELEASE'
and pqc.quotation_id = #{quotationId}
and pqc.times = #{times}

SELECT * FROM prj_quotation_cashflow pqc WHERE pqc.cf_item = 1 and pqc.cf_type = 1 and pqc.times != 1 and pqc.cf_direction = 'INFLOW' AND pqc.cf_status = 'RELEASE'
and pqc.quotation_id = #{quotationId}
order by pqc.times asc

SELECT max(pqc.due_date)due_date, max(pqc.fin_income_date) fin_income_date FROM prj_quotation_cashflow pqc
pqc.quotation_id = #{quotationId}
and pqc.cf_item = 1

select sum(tab.due_amount) due_amount,tab.due_date,sum(tab.net_due_amount) net_due_amount from( select a.cf_item,a.due_date,
( case when a.business_type='LEASE' and a.vatable_prin_flag = 'N' and a.cf_item in (0,90) then -a.due_amount when a.business_type='LEASE' and a.vatable_prin_flag = 'N' and a.cf_item = 1 then (a.net_principal+a.interest) when a.cf_direction='INFLOW' then a.due_amount when a.cf_direction='OUTFLOW' then -a.due_amount end )due_amount,
( case when a.cf_direction = 'INFLOW' then a.net_due_amount when a.business_type='LEASE' and a.vatable_prin_flag = 'N' and a.cf_item in (0,90) then -a.due_amount when a.cf_direction = 'OUTFLOW' then -nvl(a.net_due_amount,a.due_amount) end )net_due_amount
from ( select pqc.times, pqc.cf_direction, pqc.cf_item, pqc.net_principal,pqc.interest, pqc.due_date,pqc.due_amount,pqc.quotation_cashflow_id, case when pqc.cf_item = 91 then pqc.due_amount else pqc.net_due_amount end net_due_amount, pq.business_type,pq.vatable_prin_flag from prj_quotation_cashflow pqc,prj_quotation pq where pqc.quotation_id = pq.quotation_id
and pqc.quotation_id = #{quotationId}
)a )tab GROUP BY tab.due_date order by tab.due_date

select * from (
select * from prj_quotation_cashflow pqc where
pqc.quotation_id = #{quotationId}
and pqc.cf_item = 1
and pqc.due_date < #{dueDate}
order by due_date desc
) where rownum = 1

select * from (
select * from prj_quotation_cashflow pqc where
pqc.quotation_id = #{quotationId}
and pqc.cf_item = 1
and pqc.due_date >= #{dueDate}
order by due_date
) where rownum = 1

SELECT t.*, (select v.MEANING from sys_code_value_b_v v where v.code_value= status_n and v.CODE='ALIPAY_ORDER.STATUS') as status, ( CASE WHEN t.total_write_off_amount = 0 THEN '未核销' WHEN t.total_due_amount > t.total_write_off_amount THEN '部分核销' WHEN t.total_due_amount = t.total_write_off_amount THEN '完全核销' END ) AS total_write_off_flag_n FROM ( SELECT ccc.*, ROUND(ccc.principal + ccc.interest + NVL((SELECT SUM(cf.due_amount) FROM con_contract_cashflow cf WHERE cf.contract_id = ccc.contract_id AND cf.times = ccc.times AND cf.cf_item = 9), 0), 2) AS total_due_amount, ROUND(ccc.received_amount + NVL((SELECT SUM(cf.received_amount) FROM con_contract_cashflow cf WHERE cf.contract_id = ccc.contract_id AND cf.times = ccc.times AND cf.cf_item = 9), 0), 2) AS total_write_off_amount, (nvl( (SELECT v.MEANING FROM sys_code_value_b_v v WHERE v.code = 'TRANSFERPAYMENTFLAG' AND v.code_value = ccc.transfer_payment_flag), '否' )) AS transfer_payment_flag_n, (nvl((SELECT v.MEANING FROM sys_code_value_b_v v WHERE v.code = 'STOPWITHHOLDFLAG' AND v.code_value = ccc.stop_withhold_flag),'否')) AS stop_withhold_flag_n, -- 使用 MAX() 或 MIN() 确保返回单行数据 (SELECT nvl(MAX(ct.transaction_num), '无') FROM csh_transaction ct JOIN csh_write_off cw ON ct.transaction_id = cw.csh_transaction_id WHERE cw.cashflow_id = ccc.cashflow_id GROUP BY cw.cashflow_id) AS transaction_num, (SELECT contract_number FROM con_contract cc WHERE cc.contract_id = ccc.contract_id) AS contract_number, (SELECT project_id FROM con_contract cc WHERE cc.contract_id = ccc.contract_id) AS project_id, (SELECT m.bp_name FROM con_contract cc JOIN hls_bp_master m ON cc.tenant_id = m.bp_id WHERE cc.contract_id = ccc.contract_id) AS tenant_id_n, (nvl((SELECT SUM(cf.due_amount) FROM con_contract_cashflow cf WHERE cf.contract_id = ccc.contract_id AND cf.times = ccc.times AND cf.cf_item = 9),0)) AS penalty_amount, ( SELECT status FROM ( SELECT status, order_id FROM GT_ALIPAY_ORDER gao where gao.cashflow_id=ccc.cashflow_id ORDER BY order_id DESC ) WHERE ROWNUM = 1) AS status_n, (SELECT message FROM ( SELECT message, order_id FROM GT_ALIPAY_ORDER gao where gao.cashflow_id=ccc.cashflow_id ORDER BY order_id DESC ) WHERE ROWNUM = 1) AS message, (SELECT last_received_date FROM ( SELECT last_received_date, order_id FROM GT_ALIPAY_ORDER gao where gao.cashflow_id=ccc.cashflow_id ORDER BY order_id DESC ) WHERE ROWNUM = 1) AS last_received_date_n, '支付宝' AS withholding_party, nvl((select hbm.BP_NAME from PRJ_PROJECT pp, CON_CONTRACT cc , HLS_BP_MASTER hbm where cc.CONTRACT_ID = ccc.contract_id and cc.PROJECT_ID = pp.PROJECT_ID and hbm.BP_ID = pp.TENANT_ID and pp.alipay_status = 'ACTIVATED'), '') bp_name, nvl((select hbm.ID_CARD_NO from PRJ_PROJECT pp, CON_CONTRACT cc , HLS_BP_MASTER hbm where cc.CONTRACT_ID = ccc.contract_id and cc.PROJECT_ID = pp.PROJECT_ID and hbm.BP_ID = pp.TENANT_ID and pp.alipay_status = 'ACTIVATED'), 0) account_number FROM CON_CONTRACT_CASHFLOW ccc where due_date <= CURRENT_DATE and ccc.cf_direction='INFLOW' and (ccc.transfer_payment_flag is null or ccc.transfer_payment_flag='N') and cf_item !=13 and cf_item !=9 ) t
AND t.tenant_id_N LIKE CONCAT(concat('%', #{tenantIdN}), '%')
AND t.contract_number LIKE CONCAT(concat('%', #{contractNumber}), '%')
AND (SELECT MAX( CASE WHEN c.total_write_off_amount = 0 THEN '未核销' WHEN c.total_due_amount > c.total_write_off_amount THEN '部分核销' WHEN c.total_due_amount = c.total_write_off_amount THEN '完全核销' END ) FROM ( SELECT ccc.*, ROUND(ccc.principal + ccc.interest + NVL((SELECT SUM(cf.due_amount) FROM con_contract_cashflow cf WHERE cf.contract_id = ccc.contract_id AND cf.times = ccc.times AND cf.cf_item = 9), 0), 2) AS total_due_amount, ROUND(ccc.received_amount + NVL((SELECT SUM(cf.received_amount) FROM con_contract_cashflow cf WHERE cf.contract_id = ccc.contract_id AND cf.times = ccc.times AND cf.cf_item = 9), 0), 2) AS total_write_off_amount FROM CON_CONTRACT_CASHFLOW ccc ) c WHERE c.cashflow_id = t.cashflow_id) LIKE CONCAT(concat('%',#{totalWriteOffFlagN}),'%')
AND TO_CHAR(t.due_date, 'yyyy-MM-dd') BETWEEN #{dueDateFrom} AND #{dueDateTo}
AND t.transaction_num LIKE CONCAT(concat('%', #{transactionNum}), '%')
AND stop_withhold_flag = #{stopWithholdFlag}
AND status_n = #{status}
AND withholding_party = #{withholdingParty}
order by due_date desc
